public class Main {
    static int numSubseq(int[] nums, int target) {
        int MOD = 1_000_000_007;
        java.util.Arrays.sort(nums);
        int n = nums.length;
        long[] pow2 = new long[n];
        pow2[0] = 1;
        for (int i = 1; i < n; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;

        long ans = 0;
        for (int i = 0; i < n; i++) {
            int j = n - 1;
            while (j >= i && nums[i] + nums[j] > target) j--;      // re-scan downward for every i
            if (j >= i) ans = (ans + pow2[j - i]) % MOD;
        }
        return (int) ans;
    }
}

