def num_subseq(nums, target):
    MOD = 1_000_000_007
    nums = sorted(nums)
    n = len(nums)
    pow2 = [1] * n
    for i in range(1, n):
        pow2[i] = (pow2[i - 1] * 2) % MOD

    left, right = 0, n - 1
    ans = 0
    while left <= right:
        if nums[left] + nums[right] <= target:
            ans = (ans + pow2[right - left]) % MOD    # every index strictly between is free to include
            left += 1
        else:
            right -= 1                                  # too large to pair with this left, or any left after it
    return ans

